optimization-x004.code:
#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
int shares=10,periods=4;
double eta=0.2,risk=0.1;
vector<vector<double>>dp(periods+1,vector<double>(shares+1,1e100));
dp[periods][0]=0;
for(int t=periods-1;t>=0;t--)
    for(int inventory=0;inventory<=shares;inventory++)
        for(int sell=0;sell<=inventory;sell++){
            double future=dp[t+1][inventory-sell];
            double cost=eta*sell*sell+risk*(inventory-sell)*(inventory-sell);
            dp[t][inventory]=min(dp[t][inventory],cost+future);
        }
cout<<"optimal execution cost "<<dp[0][shares]<<"\n";
return 0;
}

